// Monta os objetos de produto
const products = rawProducts.map(([name, description, priceStr, costPriceStr, stock]) => ({
  name,
  description,
  price: parseBRL(priceStr),
  costPrice: parseBRL(costPriceStr),
  stock,
  imageUrl: '',
}));

// Função para inserir um produto via fetch (Node.js 18+)
async function insertProduct(product, index) {
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(product),
    });

    if (!response.ok) {
      const err = await response.text();
      console.error(`❌ [${index + 1}] ERRO ao inserir "${product.name}": ${err}`);
      return false;
    }

    const data = await response.json();
    console.log(`✅ [${index + 1}/${products.length}] Inserido: "${product.name}" (id: ${data.id})`);
    return true;
  } catch (err) {
    console.error(`❌ [${index + 1}] Falha de rede ao inserir "${product.name}": ${err.message}`);
    return false;
  }
}

async function main() {
  console.log(`\n🚀 Iniciando inserção de ${products.length} produtos...\n`);
  let success = 0;
  let failed = 0;

  for (let i = 0; i < products.length; i++) {
    const ok = await insertProduct(products[i], i);
    if (ok) success++;
    else failed++;
    // Pequena pausa para não sobrecarregar o servidor
    await new Promise(r => setTimeout(r, 50));
  }

  console.log(`\n========================================`);
  console.log(`✅ Inseridos com sucesso: ${success}`);
  console.log(`❌ Falhas: ${failed}`);
  console.log(`Total: ${products.length}`);
  console.log(`========================================\n`);
}

main();
